使用其他节点修改参数

前面提到过，ros2中参数通信实际上是通过服务来实现的，因此我们可以使用其他节点去调用参数设置服务来修改另一个节点的参数值。下面是一个简单的示例，展示了如何在一个客户端节点中调用参数设置服务来修改另一个节点的参数值。

#include "rclcpp/rclcpp.hpp"
#include "rcl_interfaces/msg/parameter_value.hpp"
#include "rcl_interfaces/msg/parameter_type.hpp"
#include "rcl_interfaces/srv/set_parameters.hpp"

using SetParameters = rcl_interfaces::srv::SetParameters;

class ParamChange : public rclcpp::Node
{
    private:


    public:
        ParamChange() : Node("param_change")
        {

        }
        // 调用服务端的set_parameters服务
        SetParameters::Response::SharedPtr call_set_parameters(const rcl_interfaces::msg::Parameter &param)
        {
            auto param_client = this->create_client<SetParameters>("/param_show/set_parameters");// 创建客户端，连接到param_show节点的set_parameters服务

            // 等待服务端上线
            while(!param_client->wait_for_service(std::chrono::seconds(1)))
            {
                if(!rclcpp::ok())
                {
                    RCLCPP_ERROR(this->get_logger(), "Waiting for service interrupted, exiting.");
                    return nullptr;
                }
                RCLCPP_INFO(this->get_logger(), "Service not available, waiting again...");
            }

            // 构造请求的对象
            auto request = std::make_shared<SetParameters::Request>();
            request->parameters.push_back(param);

            // 发送请求
            auto future = param_client->async_send_request(request);
            // 等待响应
            rclcpp::spin_until_future_complete(this->get_node_base_interface(), future);

            auto response = future.get();
            return response;
        }

        // 更新参数
        void update_server_param_num1(int num1)
        {
            // 创建参数对象
            auto param = rcl_interfaces::msg::Parameter();
            param.name = "num1";
            // 创建参数值

            auto param_value = rcl_interfaces::msg::ParameterValue(); // 创建参数值对象
            // 设置参数值之前必须指定参数类型，否则会报错
            param_value.type = rcl_interfaces::msg::ParameterType::PARAMETER_INTEGER;
            param_value.integer_value = num1;
            param.value = param_value; // 将参数值对象赋值给参数对象
            // 请求更新参数
            auto response = call_set_parameters(param); // 调用服务端的set_parameters服务
            if(response == nullptr)
            {
                RCLCPP_ERROR(this->get_logger(), "Failed to call set_parameters service.");
                return;
            }
            for(auto result : response->results)
            {
                if(result.successful)
                {
                    RCLCPP_INFO(this->get_logger(), "Parameter 'num1' updated successfully.");
                }
                else
                {
                    RCLCPP_ERROR(this->get_logger(), "Failed to update parameter 'num1'.Reason: %s", result.reason.c_str());
                }
            }
        }

